     7	const { createApp } = require('../src/app');
     8	
     9	const ADMIN = { email: 'admin@example.com', password: 'admin-password', name: 'Admin' };
    10	const PASSWORD = 'correct-horse';
    11	
    12	async function startApp(t, options = {}) {
    13	  const reportDir = fs.mkdtempSync(path.join(os.tmpdir(), 'orders-reports-'));
    14	  const app = createApp({ secret: 'test-secret', reportDir, admin: ADMIN, ...options });
    15	  const port = await app.listen(0);
    16	  t.after(async () => {
    17	    await app.close();
    18	    fs.rmSync(reportDir, { recursive: true, force: true });
    19	  });
    20	
    21	  function call(method, urlPath, { body, token } = {}) {
    22	    return new Promise((resolve, reject) => {
    23	      const payload = body === undefined ? undefined : JSON.stringify(body);
    24	      const headers = {};
    25	      if (payload !== undefined) headers['content-type'] = 'application/json';
    26	      if (token) headers.authorization = `Bearer ${token}`;
    27	      const req = http.request({ host: '127.0.0.1', port, method, path: urlPath, headers, agent: false }, (res) => {
    28	        const chunks = [];
    29	        res.on('data', (chunk) => chunks.push(chunk));
    30	        res.on('end', () => {
    31	          const text = Buffer.concat(chunks).toString('utf8');
    32	          const isJson = (res.headers['content-type'] || '').startsWith('application/json');
    33	          resolve({ status: res.statusCode, body: isJson && text ? JSON.parse(text) : undefined, text });
    34	        });
    35	      });
    36	      req.on('error', reject);
    37	      req.end(payload);
    38	    });
    39	  }
    40	
    41	  async function login(email, password = PASSWORD) {
    42	    const res = await call('POST', '/sessions', { body: { email, password } });
    43	    return res.body.token;
    44	  }
    45	
    46	  async function signUp(email, name = 'Customer') {
    47	    await call('POST', '/users', { body: { email, password: PASSWORD, name } });
    48	    return login(email);
    49	  }
    50	
    51	  return { call, login, signUp, reportDir, adminToken: await login(ADMIN.email, ADMIN.password) };
    52	}
    53	
    54	module.exports = { startApp, PASSWORD };
