'use strict';

// Single owner of the currency rule: amounts are exact to the cent. Every
// total, comparison and stored value passes through integer cents, so no
// binary floating-point sum ever reaches an order total or a payment check.
const CENTS_PER_UNIT = 100;

function isAmount(value) {
  return typeof value === 'number'
    && Number.isFinite(value)
    && value > 0
    && Math.abs(value * CENTS_PER_UNIT - Math.round(value * CENTS_PER_UNIT)) < 1e-6;
}

function toCents(amount) {
  return Math.round(amount * CENTS_PER_UNIT);
}

function fromCents(cents) {
  return cents / CENTS_PER_UNIT;
}

function totalCents(items) {
  return items.reduce((cents, item) => cents + toCents(item.unitPrice) * item.quantity, 0);
}

module.exports = { isAmount, toCents, fromCents, totalCents };
