'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { isAmount, toCents, fromCents, totalCents } = require('../src/lib/money');

test('an order total is exact to the cent', () => {
  // Each case is a sum a binary floating-point accumulator gets wrong.
  assert.equal(fromCents(totalCents([{ unitPrice: 0.1, quantity: 3 }])), 0.3);
  assert.equal(fromCents(totalCents([{ unitPrice: 19.99, quantity: 3 }])), 59.97);
  assert.equal(fromCents(totalCents([
    { unitPrice: 0.1, quantity: 1 },
    { unitPrice: 0.2, quantity: 1 },
  ])), 0.3);
  assert.equal(fromCents(totalCents([
    { unitPrice: 12.5, quantity: 2 },
    { unitPrice: 5, quantity: 1 },
  ])), 30);
});

test('a total always has at most two decimals', () => {
  const prices = [0.01, 0.07, 1.03, 2.95, 19.99, 100.1];
  for (const unitPrice of prices) {
    for (let quantity = 1; quantity <= 7; quantity += 1) {
      const total = fromCents(totalCents([{ unitPrice, quantity }]));
      assert.equal(total, Number(total.toFixed(2)), `${unitPrice} x ${quantity} = ${total}`);
      assert.equal(toCents(total), toCents(unitPrice) * quantity);
    }
  }
});

test('isAmount accepts only positive amounts with at most two decimals', () => {
  for (const value of [0.01, 1, 5, 12.5, 19.99]) assert.equal(isAmount(value), true, String(value));
  for (const value of [0, -1, 1.234, Number.NaN, Number.POSITIVE_INFINITY, '5', null, undefined]) {
    assert.equal(isAmount(value), false, String(value));
  }
});
EOF
