const { paginate } = require('../src/lib/pagination');

const items = (count) => Array.from({ length: count }, (_, index) => index);

test('totalPages counts every page needed to show every item', () => {
  // README: totalPages is the number of pages needed to show every item, at
  // least 1. A partial last page still counts.
  assert.equal(paginate(items(25), { pageSize: 20 }).totalPages, 2);
  assert.equal(paginate(items(21), { pageSize: 20 }).totalPages, 2);
  assert.equal(paginate(items(41), { pageSize: 20 }).totalPages, 3);
  assert.equal(paginate(items(40), { pageSize: 20 }).totalPages, 2);
  assert.equal(paginate(items(1), { pageSize: 20 }).totalPages, 1);
  assert.equal(paginate(items(0), { pageSize: 20 }).totalPages, 1);
});

test('every item is reachable through the reported pages', () => {
  const all = items(25);
  const seen = [];
  const { totalPages, pageSize } = paginate(all, { pageSize: 10 });
  for (let page = 1; page <= totalPages; page += 1) seen.push(...paginate(all, { page, pageSize }).items);
  assert.deepEqual(seen, all);
});

test('page and pageSize fall back to their defaults and clamp to the maximum', () => {
  assert.deepEqual(
    { page: 1, pageSize: 20 },
    (({ page, pageSize }) => ({ page, pageSize }))(paginate(items(5), {})),
  );
  assert.equal(paginate(items(5), { pageSize: '0' }).pageSize, 20);
  assert.equal(paginate(items(5), { page: 'abc' }).page, 1);
  assert.equal(paginate(items(500), { pageSize: '1000' }).pageSize, 100);
  assert.deepEqual(paginate(items(5), { page: '99' }).items, []);
});
