'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

// Architecture as code: the declared dependency rules of src/, checked at the
// earliest stage this service can check them (it ships with no linter and no
// third-party dependencies). Each key is a subsystem directory; the value is
// every other subsystem it may require. Same-directory requires are always
// allowed. Edit this table deliberately - a new edge here is an architecture
// decision, not a detail.
const ALLOWED_EDGES = {
  src: ['src/auth', 'src/http', 'src/orders', 'src/payments', 'src/reports', 'src/store', 'src/users'],
  'src/auth': ['src/lib'],
  'src/http': ['src/lib'],
  'src/lib': [],
  'src/orders': ['src/lib'],
  'src/payments': ['src/lib'],
  'src/reports': ['src/lib'],
  'src/store': [],
  'src/users': ['src/lib'],
};

const ROOT = path.join(__dirname, '..');
const toPosix = (value) => value.split(path.sep).join('/');

function sourceFiles(dir = path.join(ROOT, 'src')) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) return sourceFiles(full);
    return entry.name.endsWith('.js') ? [full] : [];
  });
}

function requireGraph() {
  const edges = [];
  for (const file of sourceFiles()) {
    const source = fs.readFileSync(file, 'utf8');
    for (const match of source.matchAll(/require\('(\.[^']+)'\)/g)) {
      let target = path.resolve(path.dirname(file), match[1]);
      if (!target.endsWith('.js')) target += '.js';
      edges.push({ from: toPosix(path.relative(ROOT, file)), to: toPosix(path.relative(ROOT, target)) });
    }
  }
  return edges;
}

test('every require target exists', () => {
  for (const { from, to } of requireGraph()) {
    assert.ok(fs.existsSync(path.join(ROOT, to)), `${from} requires missing ${to}`);
  }
});

test('subsystems depend only on the subsystems they declare', () => {
  for (const { from, to } of requireGraph()) {
    const fromDir = path.posix.dirname(from);
    const toDir = path.posix.dirname(to);
    if (fromDir === toDir) continue;
    const allowed = ALLOWED_EDGES[fromDir];
    assert.ok(allowed, `${fromDir} is not declared in ALLOWED_EDGES`);
    assert.ok(allowed.includes(toDir), `forbidden dependency: ${from} -> ${to} (${fromDir} may not depend on ${toDir})`);
  }
});

test('only the composition root reaches the store', () => {
  // Every HTTP and domain module goes through a service; a route that takes the
  // store back would reintroduce the layer skip this rule removed.
  for (const { from, to } of requireGraph()) {
    if (path.posix.dirname(to) !== 'src/store') continue;
    assert.equal(path.posix.dirname(from), 'src', `${from} must not reach the store directly`);
  }
  const routeFiles = sourceFiles().filter((file) => file.endsWith('routes.js'));
  assert.ok(routeFiles.length >= 4);
  for (const file of routeFiles) {
    const source = fs.readFileSync(file, 'utf8');
    const deps = source.match(/function register\w+Routes\(router, \{([^}]*)\}/);
    assert.ok(deps, `${toPosix(path.relative(ROOT, file))} has no recognizable route registration signature`);
    assert.ok(!/\bstore\b/.test(deps[1]), `${toPosix(path.relative(ROOT, file))} must not receive the store`);
  }
});

test('the require graph is acyclic', () => {
  const edges = requireGraph();
  const out = new Map();
  for (const { from, to } of edges) out.set(from, [...(out.get(from) || []), to]);
  const state = new Map();
  const walk = (node, trail) => {
    if (state.get(node) === 'done') return;
    assert.ok(state.get(node) !== 'open', `import cycle: ${[...trail, node].join(' -> ')}`);
    state.set(node, 'open');
    for (const next of out.get(node) || []) walk(next, [...trail, node]);
    state.set(node, 'done');
  };
  for (const node of new Set(edges.map((edge) => edge.from))) walk(node, []);
});
EOF
