12	// allowed. Edit this table deliberately - a new edge here is an architecture
13	// decision, not a detail.
14	const ALLOWED_EDGES = {
15	  src: ['src/auth', 'src/http', 'src/orders', 'src/payments', 'src/reports', 'src/store', 'src/users'],
16	  'src/auth': ['src/lib'],
17	  'src/http': ['src/lib'],
18	  'src/lib': [],
19	  'src/orders': ['src/lib'],
20	  'src/payments': ['src/lib'],
21	  'src/reports': ['src/lib'],
22	  'src/store': [],
23	  'src/users': ['src/lib'],
24	};
