26	const ROOT = path.join(__dirname, '..');
27	const toPosix = (value) => value.split(path.sep).join('/');
28	
29	function sourceFiles(dir = path.join(ROOT, 'src')) {
30	  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
31	    const full = path.join(dir, entry.name);
32	    if (entry.isDirectory()) return sourceFiles(full);
33	    return entry.name.endsWith('.js') ? [full] : [];
34	  });
35	}
