37	function requireGraph() {
38	  const edges = [];
39	  for (const file of sourceFiles()) {
40	    const source = fs.readFileSync(file, 'utf8');
41	    for (const match of source.matchAll(/require\('(\.[^']+)'\)/g)) {
42	      let target = path.resolve(path.dirname(file), match[1]);
43	      if (!target.endsWith('.js')) target += '.js';
44	      edges.push({ from: toPosix(path.relative(ROOT, file)), to: toPosix(path.relative(ROOT, target)) });
45	    }
46	  }
47	  return edges;
48	}
