56	test('subsystems depend only on the subsystems they declare', () => {
57	  for (const { from, to } of requireGraph()) {
58	    const fromDir = path.posix.dirname(from);
59	    const toDir = path.posix.dirname(to);
60	    if (fromDir === toDir) continue;
61	    const allowed = ALLOWED_EDGES[fromDir];
62	    assert.ok(allowed, `${fromDir} is not declared in ALLOWED_EDGES`);
