69	  // store back would reintroduce the layer skip this rule removed.
70	  for (const { from, to } of requireGraph()) {
71	    if (path.posix.dirname(to) !== 'src/store') continue;
72	    assert.equal(path.posix.dirname(from), 'src', `${from} must not reach the store directly`);
