88	  const state = new Map();
89	  const walk = (node, trail) => {
90	    if (state.get(node) === 'done') return;
91	    assert.ok(state.get(node) !== 'open', `import cycle: ${[...trail, node].join(' -> ')}`);
92	    state.set(node, 'open');
93	    for (const next of out.get(node) || []) walk(next, [...trail, node]);
94	    state.set(node, 'done');
95	  };
96	  for (const node of new Set(edges.map((edge) => edge.from))) walk(node, []);
