3	// Single owner of the currency rule: amounts are exact to the cent. Every
4	// total, comparison and stored value passes through integer cents, so no
5	// binary floating-point sum ever reaches an order total or a payment check.
6	const CENTS_PER_UNIT = 100;
7	
8	function isAmount(value) {
9	  if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) return false;
10	  const scaled = value * CENTS_PER_UNIT;
11	  if (Math.abs(scaled - Math.round(scaled)) >= 1e-6) return false;
12	  // At least one whole cent, and still an exact integer count of cents: below
13	  // the first bound an amount silently settles for nothing, above it the cent
14	  // count stops being representable.
15	  const cents = Math.round(scaled);
16	  return cents >= 1 && cents <= Number.MAX_SAFE_INTEGER;
17	}
18	
19	function toCents(amount) {
20	  return Math.round(amount * CENTS_PER_UNIT);
21	}
22	
23	function fromCents(cents) {
24	  return cents / CENTS_PER_UNIT;
25	}
26	
27	function totalCents(items) {
28	  return items.reduce((cents, item) => cents + toCents(item.unitPrice) * item.quantity, 0);
29	}
30	
31	module.exports = { isAmount, toCents, fromCents, totalCents };
