3	const { invalid, notFound, conflict } = require('../lib/errors');
4	const { isAmount, fromCents, totalCents } = require('../lib/money');
5	const { paginate } = require('../lib/pagination');
6	
7	// README "Order lifecycle": pending -> paid -> shipped -> delivered. A customer
8	// may cancel while pending or paid; a shipped or delivered order may not be
9	// cancelled.
10	const TRANSITIONS = {
11	  pending: ['paid', 'cancelled'],
12	  paid: ['shipped', 'cancelled'],
13	  shipped: ['delivered'],
14	  delivered: [],
15	  cancelled: [],
16	};
17	
18	function normalizeItems(items) {
19	  if (!Array.isArray(items) || items.length === 0) throw invalid('an order needs at least one item');
20	  return items.map((item) => {
21	    if (!item || typeof item.sku !== 'string' || item.sku.trim() === '') throw invalid('every item needs a sku');
22	    if (!isAmount(item.unitPrice)) throw invalid('unitPrice must be a positive amount with at most two decimals');
23	    if (!Number.isInteger(item.quantity) || item.quantity < 1) throw invalid('quantity must be a positive integer');
24	    return { sku: item.sku.trim(), unitPrice: item.unitPrice, quantity: item.quantity };
25	  });
26	}
27	
28	function createOrderService({ store }) {
29	  function create(user, { items }) {
30	    const lines = normalizeItems(items);
31	    const cents = totalCents(lines);
32	    if (!Number.isSafeInteger(cents)) throw invalid('the order total is too large to represent exactly');
33	    return store.insert('orders', {
34	      userId: user.id,
35	      items: lines,
36	      total: fromCents(cents),
37	      status: 'pending',
38	      createdAt: new Date().toISOString(),
39	    });
40	  }
41	
42	  // Not exported: reading one order without an ownership decision is not a
43	  // caller-facing capability. Admin-only lifecycle operations below are the
44	  // only callers, and the router role-gates each of them.
45	  function get(id) {
46	    const order = store.get('orders', id);
47	    if (!order) throw notFound('order not found');
48	    return order;
49	  }
50	
51	  function getOwned(user, id) {
52	    const order = get(id);
53	    if (user.role !== 'admin' && order.userId !== user.id) throw notFound('order not found');
54	    return order;
55	  }
56	
57	  function list(user, query) {
58	    const visible = store.list('orders', (order) => user.role === 'admin' || order.userId === user.id);
59	    return paginate(visible, query);
60	  }
61	
62	  function all() {
63	    return store.list('orders');
64	  }
65	
66	  function transition(order, next, patch = {}) {
67	    if (!TRANSITIONS[order.status].includes(next)) {
68	      throw conflict(`order cannot move from ${order.status} to ${next}`);
69	    }
70	    return store.update('orders', order.id, { ...patch, status: next, updatedAt: new Date().toISOString() });
71	  }
72	
73	  return {
74	    create,
75	    getOwned,
76	    list,
77	    all,
78	    cancel: (user, id) => transition(getOwned(user, id), 'cancelled'),
79	    ship: (id) => transition(get(id), 'shipped'),
80	    deliver: (id) => transition(get(id), 'delivered'),
81	    markPaid: (id, paymentId) => transition(get(id), 'paid', { paymentId }),
82	  };
83	}
84	
85	module.exports = { createOrderService };
