'use strict';

const crypto = require('node:crypto');
const { invalid, conflict } = require('../lib/errors');
const { paginate } = require('../lib/pagination');

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const MIN_PASSWORD_LENGTH = 8;

function hashPassword(password, salt) {
  return crypto.scryptSync(password, salt, 32).toString('hex');
}

function normalizeEmail(email) {
  return typeof email === 'string' ? email.trim().toLowerCase() : '';
}

function toPublic(user) {
  return { id: user.id, email: user.email, name: user.name, role: user.role, createdAt: user.createdAt };
}

function createUserService({ store }) {
  function register({ email, password, name }, role = 'customer') {
    const normalized = normalizeEmail(email);
    if (!EMAIL_PATTERN.test(normalized)) throw invalid('a valid email is required');
    if (typeof password !== 'string' || password.length < MIN_PASSWORD_LENGTH) {
      throw invalid(`password must be at least ${MIN_PASSWORD_LENGTH} characters`);
    }
    if (typeof name !== 'string' || name.trim() === '') throw invalid('name is required');
    if (store.findOne('users', (user) => user.email === normalized)) throw conflict('email already registered');
    const salt = crypto.randomBytes(16).toString('hex');
    return toPublic(store.insert('users', {
      email: normalized,
      name: name.trim(),
      role,
      salt,
      passwordHash: hashPassword(password, salt),
      createdAt: new Date().toISOString(),
    }));
  }

  function verifyCredentials(email, password) {
    if (typeof password !== 'string') return null;
    const normalized = normalizeEmail(email);
    const user = store.findOne('users', (candidate) => candidate.email === normalized);
    if (!user) return null;
    const expected = Buffer.from(user.passwordHash, 'hex');
    const actual = Buffer.from(hashPassword(password, user.salt), 'hex');
    return crypto.timingSafeEqual(expected, actual) ? toPublic(user) : null;
  }

  function find(id) {
    const user = store.get('users', id);
    return user ? toPublic(user) : null;
  }

  function list(query) {
    return paginate(store.list('users').map(toPublic), query);
  }

  return { register, verifyCredentials, find, list };
}

module.exports = { createUserService };
'use strict';

const DEFAULT_PAGE_SIZE = 20;
const MAX_PAGE_SIZE = 100;

function toPositiveInt(value, fallback) {
  const number = Number.parseInt(value, 10);
  return Number.isInteger(number) && number > 0 ? number : fallback;
}

function paginate(items, query = {}) {
  const pageSize = Math.min(toPositiveInt(query.pageSize, DEFAULT_PAGE_SIZE), MAX_PAGE_SIZE);
  const page = toPositiveInt(query.page, 1);
  const start = (page - 1) * pageSize;
  return {
    items: items.slice(start, start + pageSize),
    page,
    pageSize,
    total: items.length,
    totalPages: Math.max(1, Math.ceil(items.length / pageSize)),
  };
}

module.exports = { paginate };
'use strict';

const { invalid } = require('../lib/errors');

const MAX_BODY_BYTES = 1024 * 1024;

function sendJson(res, status, body) {
  const payload = body === undefined ? '' : JSON.stringify(body);
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

function sendText(res, status, text, contentType = 'text/plain; charset=utf-8') {
  res.writeHead(status, { 'content-type': contentType, 'content-length': Buffer.byteLength(text) });
  res.end(text);
}

function readJson(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on('data', (chunk) => {
      size += chunk.length;
      if (size <= MAX_BODY_BYTES) chunks.push(chunk);
    });
    req.on('end', () => {
      if (size > MAX_BODY_BYTES) return reject(invalid('request body too large'));
      if (size === 0) return resolve({});
      let value;
      try {
        value = JSON.parse(Buffer.concat(chunks).toString('utf8'));
      } catch {
        return reject(invalid('request body must be valid JSON'));
      }
      if (value === null || typeof value !== 'object' || Array.isArray(value)) {
        return reject(invalid('request body must be a JSON object'));
      }
      return resolve(value);
    });
    req.on('error', reject);
  });
}

module.exports = { sendJson, sendText, readJson };

