52	      let target = path.resolve(path.dirname(file), match[1]);
53	      if (!target.endsWith('.js')) target += '.js';
54	      edges.push({ from: toPosix(path.relative(ROOT, file)), to: toPosix(path.relative(ROOT, target)) });
