111	  const state = new Map();
112	  const walk = (node, trail) => {
113	    if (state.get(node) === 'done') return;
114	    assert.ok(state.get(node) !== 'open', `import cycle: ${[...trail, node].join(' -> ')}`);
115	    state.set(node, 'open');
116	    for (const next of out.get(node) || []) walk(next, [...trail, node]);
